var e=[{id:`chest`,name:"Chest",anatomicalName:`Pectoralis major & minor`,region:`upper-body`,views:[`front`],summary:"The pectorals form the bulk of the chest. The clavicular (upper) head and sternal (mid/lower) head respond to slightly different pressing angles.",functions:["Horizontal adduction: bringing the arms across the body","Shoulder flexion (upper fibres) and extension from a raised position (lower fibres)","Internal rotation of the upper arm"],recommendedSets:"10–20 hard sets per week",recommendedReps:"6–12 for presses, 10–15 for flyes",frequency:"2 sessions per week, 48–72 hours apart",techniqueTips:["Set the shoulder blades back and down before every press","Lower the weight under control to a deep, pain-free stretch","Keep the wrists stacked over the elbows at the bottom of the press","Use an incline of 15–30° to work the upper chest more"],commonMistakes:["Flaring the elbows to 90°, which shifts stress to the shoulder joint","Bouncing the bar off the chest","Shortening the range of motion to lift heavier","Losing upper-back tightness during the set"]},{id:`front-delts`,name:"Front Deltoids",anatomicalName:`Anterior deltoid`,region:`upper-body`,views:[`front`],summary:"The front head of the shoulder works hard during every press, so many lifters need little direct isolation work for it.",functions:["Shoulder flexion: raising the arm forward","Assists horizontal adduction and internal rotation"],recommendedSets:"6–12 direct sets per week (pressing counts heavily)",recommendedReps:"6–12 for overhead presses, 10–15 for raises",frequency:"2 sessions per week",techniqueTips:["Brace the core and squeeze the glutes during overhead pressing","Press the bar slightly back so it finishes over the mid-foot","Control the lowering phase rather than dropping the weight"],commonMistakes:["Excessive lower-back arch during overhead presses","Adding lots of front raises on top of a high chest-pressing volume","Using momentum on raises"]},{id:`side-delts`,name:"Side Deltoids",anatomicalName:`Lateral deltoid`,region:`upper-body`,views:[`front`,`back`],summary:"The side head gives your shoulders their width, the base of the classic V-shape. It recovers quickly and can be trained often.",functions:["Shoulder abduction: raising the arm out to the side"],recommendedSets:"10–20 sets per week",recommendedReps:`12–20`,frequency:"2–4 sessions per week",techniqueTips:["Lead with the elbows and raise the arms slightly in front of the body (scapular plane)","Stop around shoulder height and control the descent","Cables keep tension on the muscle at the bottom of the movement"],commonMistakes:["Swinging the torso to lift heavier dumbbells","Shrugging the shoulders up towards the ears","Using weights too heavy to control for 12 or more reps"]},{id:`rear-delts`,name:"Rear Deltoids",anatomicalName:`Posterior deltoid`,region:`upper-body`,views:[`back`],summary:"The rear head balances heavy pressing, keeps your shoulders healthy and adds depth to the shoulder seen from the side and back.",functions:["Horizontal abduction: pulling the arm back","Shoulder extension and external rotation"],recommendedSets:"8–16 sets per week",recommendedReps:`12–20`,frequency:"2–3 sessions per week",techniqueTips:["Think about moving the arms out and back rather than squeezing the shoulder blades","Use light loads and a deliberate tempo","Keep a slight bend in the elbows throughout"],commonMistakes:["Turning rear-delt work into a row with heavy weights","Retracting the shoulder blades so the traps take over","Neglecting the rear delts entirely"]},{id:`traps`,name:"Trapezius",anatomicalName:`Trapezius (upper, middle & lower fibres)`,region:`upper-body`,views:[`front`,`back`],summary:"A large, diamond-shaped muscle running from the skull to the mid-back. It controls the shoulder blades and supports posture.",functions:["Upper fibres: elevation of the shoulder blades (shrugging)","Middle fibres: retraction, pulling the shoulder blades together","Lower fibres: depression and upward rotation of the shoulder blades"],recommendedSets:"6–12 direct sets per week",recommendedReps:"10–15 for shrugs, 8–12 for rows",frequency:"2 sessions per week",techniqueTips:["Shrug straight up, without rolling the shoulders","Pause briefly at the top of each shrug","Heavy rows and deadlifts train the traps substantially"],commonMistakes:["Rolling the shoulders during shrugs","Using a tiny range of motion with excessive load","Overlooking the middle and lower fibres"]},{id:`lats`,name:"Latissimus Dorsi",anatomicalName:`Latissimus dorsi`,region:`upper-body`,views:[`back`],summary:"The widest muscle of the back. Well-developed lats create the width that defines a bodybuilding physique from the front and back.",functions:["Shoulder extension: pulling the arm down and back","Shoulder adduction: pulling the arm into the side","Internal rotation of the upper arm"],recommendedSets:"10–20 sets per week",recommendedReps:"6–12 for pull-ups, 8–15 for pulldowns and rows",frequency:"2 sessions per week",techniqueTips:["Initiate pulls by driving the elbows down towards the hips","Allow a full stretch at the top of pulldowns and pull-ups","Use a grip just outside shoulder width for vertical pulls"],commonMistakes:["Pulling with the biceps and shortening the range of motion","Leaning far back and turning a pulldown into a row","Using loads so heavy without straps that your form breaks down"]},{id:`rhomboids`,name:"Rhomboids",anatomicalName:`Rhomboid major & minor`,region:`upper-body`,views:[`back`],summary:"Small muscles between the spine and shoulder blades that sit beneath the trapezius. They stabilise the scapula and add mid-back thickness.",functions:["Scapular retraction","Downward rotation and elevation of the shoulder blade"],recommendedSets:"Trained with rows: 8–14 rowing sets per week",recommendedReps:`8–15`,frequency:"2 sessions per week",techniqueTips:["Squeeze the shoulder blades together at the end of each row","Let the shoulder blades protract fully on the way back for a full range of motion","Pause for one second in the contracted position"],commonMistakes:["Using momentum on rows","Short, choppy repetitions","Shrugging during the pull"]},{id:`biceps`,name:"Biceps",anatomicalName:`Biceps brachii & brachialis`,region:`upper-body`,views:[`front`],summary:"The two-headed muscle on the front of the upper arm, supported by the brachialis underneath. Both respond well to varied curl angles.",functions:["Elbow flexion","Forearm supination: turning the palm up","Assists shoulder flexion"],recommendedSets:"8–16 direct sets per week",recommendedReps:`8–15`,frequency:"2–3 sessions per week",techniqueTips:["Keep the upper arm still and the elbows close to the body","Supinate the wrist fully at the top of dumbbell curls","Lower slowly: the lowering phase is very effective","Include a stretched-position curl such as the incline curl"],commonMistakes:["Swinging the torso to move the weight","Cutting the bottom portion of the rep short","Training biceps with too much volume on top of heavy back work"]},{id:`triceps`,name:"Triceps",anatomicalName:`Triceps brachii (long, lateral & medial heads)`,region:`upper-body`,views:[`back`],summary:"The triceps make up roughly two-thirds of upper-arm mass. The long head crosses the shoulder and grows best with overhead work.",functions:["Elbow extension","Long head: shoulder extension and adduction"],recommendedSets:"8–16 direct sets per week",recommendedReps:`8–15`,frequency:"2–3 sessions per week",techniqueTips:["Keep the elbows fixed and pointing in the same direction","Use overhead extensions to load the long head in a stretch","Lock out fully and squeeze briefly at the end of each rep"],commonMistakes:["Letting the elbows flare during pushdowns","Leaning over pushdowns so the chest and shoulders assist","Overloading skull crushers, which can irritate the elbows"]},{id:`forearms`,name:"Forearms",anatomicalName:`Wrist flexors, extensors & brachioradialis`,region:`upper-body`,views:[`front`,`back`],summary:"Forearm muscles control the wrist and grip. Strong forearms support every pulling movement and complete the look of the arm.",functions:["Wrist flexion and extension","Grip strength","Brachioradialis: elbow flexion in a neutral grip"],recommendedSets:"4–10 direct sets per week",recommendedReps:"12–20 or timed holds",frequency:"2–3 sessions per week",techniqueTips:["Use hammer curls and reverse curls to train the brachioradialis","Carries and dead hangs build grip endurance","Move through the full wrist range of motion"],commonMistakes:["Relying on straps for every pulling set","Using bouncing, partial reps on wrist curls"]},{id:`rectus-abdominis`,name:"Rectus Abdominis",anatomicalName:`Rectus abdominis`,region:`core`,views:[`front`],summary:"The \"six-pack\" muscle running from the ribs to the pelvis. Its visibility depends mainly on body-fat level; training builds its thickness and strength.",functions:["Spinal flexion: curling the ribs towards the pelvis","Resists spinal extension under load"],recommendedSets:"6–12 sets per week",recommendedReps:`10–20`,frequency:"2–3 sessions per week",techniqueTips:["Think about curling the spine rather than hinging at the hips","Exhale fully at the top of every crunch","Add load progressively, just like any other muscle"],commonMistakes:["Pulling on the neck during crunches","Using hip flexors to perform sit-ups","Expecting ab training alone to reduce abdominal fat"]},{id:`obliques`,name:"Obliques",anatomicalName:`External & internal obliques`,region:`core`,views:[`front`],summary:"The obliques wrap around the sides of the torso. They rotate and side-bend the spine and, most importantly, resist rotation during heavy lifts.",functions:["Trunk rotation","Lateral flexion: bending to the side","Anti-rotation stability"],recommendedSets:"4–10 sets per week",recommendedReps:"10–15 per side",frequency:"2 sessions per week",techniqueTips:["Use anti-rotation work such as the Pallof press","Rotate slowly and avoid momentum","Keep the hips stable during cable rotations"],commonMistakes:["Twisting rapidly with momentum","Neglecting anti-rotation training"]},{id:`transverse-abdominis`,name:"Transverse Abdominis",anatomicalName:`Transversus abdominis`,region:`core`,views:[`front`],deep:!0,summary:"The deepest abdominal layer, wrapping around the torso like a corset. It is not visible on the surface, so the chart outlines it.",functions:["Increases intra-abdominal pressure for spinal stability","Compresses the abdomen, \"drawing in\" the stomach"],recommendedSets:"3–6 sets per week of bracing / stability work",recommendedReps:"20–45 second holds",frequency:"2–3 sessions per week",techniqueTips:["Practise 360° bracing: breathe into the belly and sides, then tighten","Planks and dead bugs train it effectively","Stomach vacuums can build control of the muscle"],commonMistakes:["Holding the breath without bracing","Letting the lower back sag during planks"]},{id:`erector-spinae`,name:"Lower Back",anatomicalName:`Erector spinae`,region:`core`,views:[`back`],summary:"Columns of muscle running along the spine. They hold the torso upright and keep the spine neutral during squats, deadlifts and rows.",functions:["Spinal extension","Maintains a neutral spine under load","Lateral flexion of the spine"],recommendedSets:"3–8 direct sets per week (heavy hinges count)",recommendedReps:`8–15`,frequency:"1–2 sessions per week",techniqueTips:["Keep a neutral spine and move at the hips during hinges","Back extensions with a controlled tempo build endurance","Brace before every heavy lift"],commonMistakes:["Rounding the lower back under heavy load","Hyperextending at the top of back extensions","Excessive direct volume on top of heavy deadlifts"]},{id:`quadriceps`,name:"Quadriceps",anatomicalName:`Rectus femoris & vastus lateralis, medialis, intermedius`,region:`lower-body`,views:[`front`],summary:"Four muscles on the front of the thigh that straighten the knee. They are the largest muscle group of the legs and drive squats and lunges.",functions:["Knee extension","Rectus femoris: hip flexion"],recommendedSets:"10–20 sets per week",recommendedReps:"6–12 for squats, 10–15 for leg presses and extensions",frequency:"2 sessions per week",techniqueTips:["Allow the knees to travel forward over the toes for deeper quad loading","Squat to the depth you can control with a neutral spine","Use leg extensions to train the rectus femoris"],commonMistakes:["Cutting depth to lift heavier","Knees collapsing inwards","Lifting the heels off the floor"]},{id:`hamstrings`,name:"Hamstrings",anatomicalName:`Biceps femoris, semitendinosus & semimembranosus`,region:`lower-body`,views:[`back`],summary:"The hamstrings cross both the hip and the knee, so they need both hinging (hip) and curling (knee) movements for complete development.",functions:["Knee flexion","Hip extension","Stabilises the knee"],recommendedSets:"8–16 sets per week",recommendedReps:"6–10 for hinges, 10–15 for curls",frequency:"2 sessions per week",techniqueTips:["Push the hips back and keep the shins nearly vertical on Romanian deadlifts","Include at least one curl variation each week","Seated leg curls train the hamstrings at long muscle lengths"],commonMistakes:["Rounding the back to reach lower on hinges","Lifting the hips off the pad during lying curls","Training only hip-hinge movements"]},{id:`glutes`,name:"Gluteus Maximus",anatomicalName:`Gluteus maximus`,region:`lower-body`,views:[`back`],summary:"The largest and most powerful muscle in the body. It extends the hip and is central to squatting, deadlifting, sprinting and posture.",functions:["Hip extension","External rotation of the hip","Posterior pelvic tilt"],recommendedSets:"8–16 sets per week",recommendedReps:`8–15`,frequency:"2–3 sessions per week",techniqueTips:["Drive through the whole foot and squeeze at lockout","Keep the ribs down to avoid overextending the lower back","Deep squats and lunges load the glutes in a stretch"],commonMistakes:["Hyperextending the lower back at the top of hip thrusts","Rushing repetitions without a full lockout"]},{id:`glute-medius`,name:"Gluteus Medius",anatomicalName:`Gluteus medius`,region:`lower-body`,views:[`back`],summary:"Sits on the upper, outer hip. It stabilises the pelvis on one leg and keeps the knees tracking well during squats and lunges.",functions:["Hip abduction","Pelvic stability in single-leg stance","Internal and external hip rotation"],recommendedSets:"4–10 sets per week",recommendedReps:`12–20`,frequency:"2–3 sessions per week",techniqueTips:["Lean the torso slightly forward on abduction machines","Single-leg work trains the glute medius as a stabiliser","Control the return phase"],commonMistakes:["Using momentum on abduction","Rotating the pelvis to compensate"]},{id:`calves`,name:"Calves",anatomicalName:`Gastrocnemius`,region:`lower-body`,views:[`front`,`back`],summary:"The diamond-shaped muscle on the back of the lower leg. It crosses the knee, so it is trained best with straight-leg calf raises.",functions:["Ankle plantar flexion: rising onto the toes","Assists knee flexion"],recommendedSets:"8–16 sets per week",recommendedReps:"8–15 with a pause in the stretch",frequency:"2–4 sessions per week",techniqueTips:["Pause for 1–2 seconds at the bottom stretch to remove the bounce","Rise as high as possible onto the big toe","Keep the knees straight for gastrocnemius emphasis"],commonMistakes:["Bouncing through short, fast repetitions","Bending the knees to lift more weight"]},{id:`soleus`,name:"Soleus",anatomicalName:`Soleus`,region:`lower-body`,views:[`front`,`back`],summary:"A broad, flat calf muscle beneath the gastrocnemius. Because it does not cross the knee, bent-knee calf raises train it most effectively.",functions:["Ankle plantar flexion, especially with the knee bent","Postural stability when standing"],recommendedSets:"4–10 sets per week",recommendedReps:`12–20`,frequency:"2–3 sessions per week",techniqueTips:["Use seated calf raises with the knees bent around 90°","Control the full range of motion with a pause at the bottom"],commonMistakes:["Only performing standing calf raises","Rushing through partial reps"]},{id:`hip-adductors`,name:"Hip Adductors",anatomicalName:`Adductor magnus, longus & brevis`,region:`lower-body`,views:[`front`,`back`],summary:"The inner-thigh muscles. The adductor magnus is a powerful hip extender that contributes significantly to squats and thigh size.",functions:["Hip adduction: bringing the legs together","Adductor magnus: hip extension"],recommendedSets:"4–10 sets per week",recommendedReps:`10–15`,frequency:"2 sessions per week",techniqueTips:["Wide-stance squats and deep lunges load the adductors","Adduction machines work well with a controlled stretch","Copenhagen planks build adductor strength and resilience"],commonMistakes:["Forcing an aggressive stretch with heavy load","Ignoring the adductors entirely"]},{id:`hip-abductors`,name:"Hip Abductors",anatomicalName:`Tensor fasciae latae, gluteus minimus & medius`,region:`lower-body`,views:[`front`,`back`],summary:"The outer-hip muscles that move the leg away from the body and keep the pelvis level when walking, running and lunging.",functions:["Hip abduction","Pelvic stabilisation","Internal rotation of the hip (TFL)"],recommendedSets:"4–10 sets per week",recommendedReps:`12–20`,frequency:"2–3 sessions per week",techniqueTips:["Use controlled machine or cable abductions","Banded lateral walks make a useful warm-up","Keep the torso stable and avoid swinging"],commonMistakes:["Using momentum","Rotating the hip so other muscles take over"]}];export{e as t};